"""Generated by solo-to-scale; edit `templates/tools/tests/test_finance.py` in the plugin, then run upgrade.

Money: revenue, costs, burn and runway from founder/finance.json.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

TOOLS = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(TOOLS))
import finance  # noqa: E402


def write(tmp_path: Path, data) -> Path:
    (tmp_path / "founder").mkdir(exist_ok=True)
    (tmp_path / "founder/finance.json").write_text(json.dumps(data) if not isinstance(data, str) else data, encoding="utf-8")
    return tmp_path


def test_runway_burn_and_ai_share(tmp_path, capsys):
    root = write(tmp_path, {**finance.TEMPLATE, "cash": 12000, "as_of": "2026-11-01", "monthly_revenue": 500,
                            "fixed_costs": [{"name": "Hosting", "monthly": 300}, {"name": "Ads", "monthly": 1000}],
                            "one_offs": [{"name": "Laptop", "amount": 2000, "month": "2026-11"},
                                         {"name": "Old", "amount": 99, "month": "2026-10"}]})
    m = finance.summary(finance.load(root), 200.0, "2026-11")
    assert m["set"] and m["costs"] == 1500 and m["net_burn"] == 1000
    assert m["cash_left"] == 10000 and m["runway_months"] == 10.0 and m["one_offs_total"] == 2000
    assert m["ai_share"] == round(200 / 1500, 3) and not m["profitable"]
    assert finance.main(["show", "--ai-usd", "200", "--month", "2026-11", "--root", str(root)]) == 0
    assert "runway: 10.0 months" in capsys.readouterr().out


def test_no_burn_unset_and_broken(tmp_path, capsys):
    assert not finance.summary(None, 5.0, "2026-11")["set"], "no file: nothing to show"
    assert not finance.summary(finance.TEMPLATE, 0.0, "2026-11")["set"], "the template is empty until the founder fills it"
    root = write(tmp_path, {"cash": 1000, "monthly_revenue": 900, "fixed_costs": [{"name": "Tools", "monthly": 100}]})
    m = finance.summary(finance.load(root), 50.0, "2026-11")
    assert m["runway_months"] is None and m["profitable"]
    write(tmp_path, {"cash": "lots", "fixed_costs": [{"name": "x"}]})
    assert finance.main(["check", "--root", str(tmp_path)]) == 1
    out = capsys.readouterr().out
    assert "cash must be a number" in out and "fixed_costs[0] needs name, monthly" in out
    write(tmp_path, "{nope")
    assert finance.problems(finance.load(tmp_path)) == ["founder/finance.json is not valid JSON"]
